"use client";

import { useState, type ReactNode } from "react";
import { supabase } from "../lib/supabase";

export const inputClass =
  "w-full border border-gray-200 bg-gray-50 rounded-xl p-3.5 text-gray-900 placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-pink-500 focus:bg-white transition";

  export const primaryBtn =
    "w-full bg-gradient-to-l from-pink-600 to-rose-500 text-white font-bold rounded-xl p-3.5 shadow-lg shadow-pink-200 hover:opacity-95 disabled:opacity-50 transition";

    export const fileClass =
      "block w-full text-sm text-gray-600 file:me-3 file:rounded-lg file:border-0 file:bg-pink-50 file:px-4 file:py-2 file:font-semibold file:text-pink-700";

      export type NavLink = { href: string; label: string; cta?: boolean };

      export const BROKER_LINKS: NavLink[] = [
        { href: "/dashboard", label: "الطلبات" },
          { href: "/broker/rates", label: "الأسعار" },
            { href: "/broker/subscribe", label: "الاشتراك" },
            ];

            export const ADMIN_LINKS: NavLink[] = [
              { href: "/admin", label: "الوسطاء" },
                { href: "/admin/subscriptions", label: "الاشتراكات" },
                ];

                const PUBLIC_LINKS: NavLink[] = [
                  { href: "/dashboard", label: "دخول الوسيط" },
                    { href: "/broker/register", label: "انضم كوسيط", cta: true },
                    ];

                    export function ShieldIcon({ className = "w-5 h-5" }: { className?: string }) {
                      return (
                          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"
                                strokeLinecap="round" strokeLinejoin="round" className={className}>
                                      <path d="M12 3l8 3v6c0 4.5-3.2 8.3-8 9-4.8-.7-8-4.5-8-9V6l8-3z" />
                                            <path d="M9 12l2 2 4-4" />
                                                </svg>
                                                  );
                                                  }

                                                  export function SiteHeader({
                                                    links = PUBLIC_LINKS,
                                                      onSignOut,
                                                      }: {
                                                        links?: NavLink[];
                                                          onSignOut?: () => void;
                                                          }) {
                                                            return (
                                                                <header className="sticky top-0 z-20 bg-white/90 backdrop-blur border-b border-gray-100">
                                                                      <div className="max-w-3xl mx-auto flex items-center justify-between gap-3 px-4 h-14">
                                                                              <a href="/" className="flex items-center gap-2 shrink-0">
                                                                                        <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-pink-500 to-rose-600 text-white font-bold flex items-center justify-center">
                                                                                                    ه
                                                                                                              </div>
                                                                                                                        <span className="font-extrabold text-lg text-gray-900">هاتلي</span>
                                                                                                                                </a>
                                                                                                                                        <nav className="flex items-center gap-3 text-sm overflow-x-auto">
                                                                                                                                                  {links.map((l) =>
                                                                                                                                                              l.cta ? (
                                                                                                                                                                            <a key={l.href} href={l.href}
                                                                                                                                                                                            className="font-semibold text-pink-600 border border-pink-200 rounded-full px-4 py-1.5 hover:bg-pink-50 whitespace-nowrap">
                                                                                                                                                                                                            {l.label}
                                                                                                                                                                                                                          </a>
                                                                                                                                                                                                                                      ) : (
                                                                                                                                                                                                                                                    <a key={l.href} href={l.href}
                                                                                                                                                                                                                                                                    className="text-gray-600 hover:text-pink-600 whitespace-nowrap">
                                                                                                                                                                                                                                                                                    {l.label}
                                                                                                                                                                                                                                                                                                  </a>
                                                                                                                                                                                                                                                                                                              )
                                                                                                                                                                                                                                                                                                                        )}
                                                                                                                                                                                                                                                                                                                                  {onSignOut && (
                                                                                                                                                                                                                                                                                                                                              <button onClick={onSignOut}
                                                                                                                                                                                                                                                                                                                                                            className="text-gray-500 hover:text-red-600 whitespace-nowrap">
                                                                                                                                                                                                                                                                                                                                                                          خروج
                                                                                                                                                                                                                                                                                                                                                                                      </button>
                                                                                                                                                                                                                                                                                                                                                                                                )}
                                                                                                                                                                                                                                                                                                                                                                                                        </nav>
                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                  </header>
                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                    export function SiteFooter() {
                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                          <footer className="border-t border-gray-100 bg-white py-6 text-center text-xs text-gray-500">
                                                                                                                                                                                                                                                                                                                                                                                                                                <p className="font-bold text-gray-700 mb-1">هاتلي</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                      <p>منصة وسيطة تربطك بوسطاء موثقين. هاتلي ليست تابعة لشي إن.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                          </footer>
                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                            export function PageShell({
                                                                                                                                                                                                                                                                                                                                                                                                                                              children, links, onSignOut, title, subtitle, size = "md",
                                                                                                                                                                                                                                                                                                                                                                                                                                              }: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                children: ReactNode;
                                                                                                                                                                                                                                                                                                                                                                                                                                                  links?: NavLink[];
                                                                                                                                                                                                                                                                                                                                                                                                                                                    onSignOut?: () => void;
                                                                                                                                                                                                                                                                                                                                                                                                                                                      title?: string;
                                                                                                                                                                                                                                                                                                                                                                                                                                                        subtitle?: string;
                                                                                                                                                                                                                                                                                                                                                                                                                                                          size?: "sm" | "md" | "lg";
                                                                                                                                                                                                                                                                                                                                                                                                                                                          }) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            const width = size === "sm" ? "max-w-sm" : size === "lg" ? "max-w-3xl" : "max-w-md";
                                                                                                                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="min-h-screen bg-gray-50 flex flex-col">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <SiteHeader links={links} onSignOut={onSignOut} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <main className="flex-1 px-4 py-8">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className={`mx-auto space-y-4 ${width}`}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {title && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="mb-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h1 className="text-2xl font-extrabold text-gray-900">{title}</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {subtitle && <p className="text-sm text-gray-500 mt-1">{subtitle}</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {children}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <SiteFooter />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  export function Card({ children, className = "" }: { children: ReactNode; className?: string }) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className={`bg-white rounded-2xl shadow-sm border border-gray-100 p-4 ${className}`}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {children}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    export function Field({ label, children }: { label: string; children: ReactNode }) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <label className="block text-sm font-semibold text-gray-700 mb-1.5">{label}</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {children}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            export function Notice({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              type = "error", children,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                type?: "error" | "success" | "warning";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  children: ReactNode;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const styles = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        error: "bg-red-50 text-red-700 border-red-100",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            success: "bg-green-50 text-green-700 border-green-100",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                warning: "bg-yellow-50 text-yellow-800 border-yellow-200",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p className={`text-sm rounded-xl border p-3 ${styles[type]}`}>{children}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          export function Loading() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="min-h-screen flex items-center justify-center bg-gray-50">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="w-8 h-8 border-4 border-pink-200 border-t-pink-600 rounded-full animate-spin" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            export function LoginCard({ title, subtitle }: { title: string; subtitle?: string }) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const [email, setEmail] = useState("");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const [password, setPassword] = useState("");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const [error, setError] = useState("");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const [busy, setBusy] = useState(false);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      async function handleLogin(e: React.FormEvent) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setBusy(true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  setError("");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const { error } = await supabase.auth.signInWithPassword({ email, password });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (error) setError("البريد أو كلمة المرور غير صحيحة");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setBusy(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <form onSubmit={handleLogin}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            className="bg-white rounded-3xl shadow-xl shadow-pink-100/50 p-6 space-y-4 mt-6">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="text-center space-y-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="w-12 h-12 mx-auto rounded-full bg-pink-50 text-pink-600 flex items-center justify-center">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <ShieldIcon className="w-6 h-6" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h1 className="text-xl font-extrabold text-gray-900">{title}</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {subtitle && <p className="text-sm text-gray-500">{subtitle}</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <input type="email" required dir="ltr" value={email}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onChange={(e) => setEmail(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        placeholder="البريد الإلكتروني" className={inputClass} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <input type="password" required dir="ltr" value={password}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onChange={(e) => setPassword(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              placeholder="كلمة المرور" className={inputClass} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button type="submit" disabled={busy} className={primaryBtn}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {busy ? "جاري الدخول..." : "دخول"}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {error && <Notice>{error}</Notice>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }